import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.wolinski.shop.customers.api.CustomerFacade;
import com.wolinski.shop.money.Money;
import com.wolinski.shop.notifications.api.MailTransport;
import com.wolinski.shop.orders.api.OrderFacade;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class OrderCancellationMailTest {

    record Mail(String address, String subject, String body) {
    }

    @Test
    void cancellingAnOrderMailsTheCustomerExactlyOnce() {
        List<Mail> sent = new ArrayList<>();
        try (var shop = shop(sent)) {
            shop.getBean(CustomerFacade.class).register("c-1", "anna@example.com");
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

            orders.cancel(id);
            orders.cancel(id);

            assertEquals(1, sent.size());
            Mail mail = sent.get(0);
            assertEquals("anna@example.com", mail.address());
            assertTrue(mail.subject().contains(id), mail.subject());
        }
    }

    @Test
    void anOrderWithoutACancellationSendsNothing() {
        List<Mail> sent = new ArrayList<>();
        try (var shop = shop(sent)) {
            shop.getBean(CustomerFacade.class).register("c-1", "anna@example.com");
            shop.getBean(OrderFacade.class).place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

            assertEquals(0, sent.size());
        }
    }

    @Test
    void aCustomerWithoutAnAddressIsNotMailed() {
        List<Mail> sent = new ArrayList<>();
        try (var shop = shop(sent)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-unknown", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

            orders.cancel(id);

            assertEquals(0, sent.size());
            assertEquals("CANCELLED", orders.summary(id).status());
        }
    }

    private static AnnotationConfigApplicationContext shop(List<Mail> sent) {
        var shop = new AnnotationConfigApplicationContext();
        shop.register(ShopConfig.class);
        MailTransport recorder = (address, subject, body) -> sent.add(new Mail(address, subject, body));
        shop.registerBean(MailTransport.class, () -> recorder, definition -> definition.setPrimary(true));
        shop.refresh();
        return shop;
    }
}
}
